import { it, expect } from 'vitest'
import { userEvent } from 'vitest/browser'
import { waitForDelay } from '@orkestrel/test'
import { makeElement, makeStyle, readBox, readStyles, readStack, readTabs, settleFrame, writeReading } from './helpers.js'

it('measures modal UA differences and neutralization', async () => {
	const trigger=makeElement('button');trigger.id='opener';trigger.textContent='Open'
	const control=makeElement('div','modal fade show','display:block')
	control.innerHTML='<div class="modal-dialog"><div class="modal-content"><button>First</button><button>Last</button></div></div>'
	const backdrop=makeElement('div','modal-backdrop fade show')
	const controlChild=control.querySelector('.modal-dialog')
	if(!controlChild) throw new Error('Missing control dialog')
	const baseline={style:readStyles(control),box:readBox(control),child:readBox(controlChild)}
	control.remove();backdrop.remove()
	const high=makeElement('div','','position:fixed;inset:0;z-index:2147483647;background:red');high.id='high-sibling'
	const dialog=makeElement('dialog','modal fade')
	dialog.innerHTML='<div class="modal-dialog"><div class="modal-content"><button id="first">First</button><button id="last">Last</button></div></div>'
	const child=dialog.querySelector('.modal-dialog');const last=dialog.querySelector('#last')
	if(!child || !(last instanceof HTMLElement))throw new Error('Missing native dialog')
	const events: unknown[]=[]
	dialog.addEventListener('cancel',event=>events.push({event:'cancel',cancelable:event.cancelable}))
	dialog.addEventListener('close',()=>events.push({event:'close'}))
	trigger.focus();dialog.showModal();dialog.classList.add('show');await waitForDelay(360)
	const raw={style:readStyles(dialog),box:readBox(dialog),focus:document.activeElement?.id}
	dialog.close();makeStyle('dialog.modal[open] { display: block; }');trigger.focus();dialog.showModal();await settleFrame()
	const initial={style:readStyles(dialog),box:readBox(dialog),child:readBox(child),backdrop:readStyles(dialog,'::backdrop'),stack:readStack(innerWidth-10,innerHeight-10),focus:document.activeElement?.id,tabs:await readTabs(last)}
	const declarations='dialog.modal { margin: 0; border: 0; padding: 0; max-width: none; max-height: none; color: inherit; background: transparent; }'
	makeStyle(declarations);await settleFrame()
	const neutralized={style:readStyles(dialog),box:readBox(dialog),child:readBox(child)}
	const differences=Object.keys(baseline.style).filter(key=>baseline.style[key]!==neutralized.style[key])
	trigger.focus();const outsideFocus={attempt:'opener',actual:document.activeElement?.id}
	await userEvent.keyboard('{Escape}');await waitForDelay(80)
	const closed={open:dialog.open,events,focus:document.activeElement?.id}
	expect(initial.style['border-width']).not.toBe(baseline.style['border-width'])
	expect(neutralized.box).toEqual(baseline.box)
	expect(differences).toEqual([])
	await writeReading('dialog-modal',2,{viewport:{width:innerWidth,height:innerHeight},declarations:declarations+' dialog.modal[open] { display: block; }'}, {raw,initial,neutralized,differences,outsideFocus,closed},{expected:'The ordinary div has no dialog UA border or margin; normalization restores its box.',reading:baseline},'A native modal requires UA box normalization and display:block when open; Escape and focus behavior are measured independently.')
	dialog.remove();high.remove();trigger.remove()
})

it('measures top layer insertion versus z-index', async () => {
	const low=makeElement('div','','position:fixed;left:100px;top:100px;width:160px;height:160px;z-index:1;background:red');low.id='low'
	const dialog=makeElement('dialog','modal show','display:block;margin:0;border:0;padding:0;max-width:none;max-height:none')
	dialog.id='dialog';dialog.showModal()
	const dropdown=makeElement('div','dropdown-menu show','position:fixed;inset:auto;left:100px;top:100px;width:160px;height:160px;margin:0',dialog);dropdown.id='dropdown';dropdown.popover='manual';dropdown.showPopover()
	const tooltip=makeElement('div','tooltip show','position:fixed;inset:auto;left:100px;top:100px;width:160px;height:160px;margin:0;background:blue',dialog);tooltip.id='tooltip';tooltip.popover='manual';tooltip.showPopover()
	const container=makeElement('div','toast-container position-fixed','left:100px;top:100px',dialog)
	const toast=makeElement('div','toast show','width:160px;height:160px',container);toast.id='toast'
	await settleFrame()
	const first=readStack(120,120)
	dropdown.hidePopover();dropdown.showPopover();await settleFrame()
	const reordered=readStack(120,120)
	tooltip.hidePopover();dropdown.hidePopover();await settleFrame()
	const underlying=readStack(120,120)
	const zindexes={modal:getComputedStyle(dialog).getPropertyValue('--bs-modal-zindex'),dropdown:getComputedStyle(dropdown).getPropertyValue('--bs-dropdown-zindex'),tooltip:getComputedStyle(tooltip).getPropertyValue('--bs-tooltip-zindex'),toast:getComputedStyle(container).getPropertyValue('--bs-toast-zindex')}
	const backdrop=makeElement('div','modal-backdrop');zindexes['backdrop']=getComputedStyle(backdrop).getPropertyValue('--bs-backdrop-zindex');backdrop.remove()
	expect(first[0]).toBe('tooltip');expect(reordered[0]).toBe('dropdown');expect(underlying[0]).toBe('toast')
	await writeReading('top-layer',10,{point:{x:120,y:120},opening:['dialog','dropdown','tooltip']},{first,reordered,underlying,zindexes},{expected:'A document-layer z-index:1 element cannot outrank the modal; shown top-layer popovers can.',reading:{lowInStack:first.indexOf('low'),top:first[0],underlying}},'Top-layer insertion order outranks Bootstrap z-index; reopening dropdown raises it over tooltip and toast.')
	dialog.close();dialog.remove();low.remove()
})

it('measures invoker commands and cancellation', async () => {
	const button=makeElement('button');button.textContent='Invoke'
	const dialog=makeElement('dialog','modal');dialog.id='command-dialog'
	makeStyle('dialog.modal[open] { display:block; }')
	const menu=makeElement('div','dropdown-menu show','left:150px;top:150px');menu.id='command-menu';menu.popover='auto'
	const events:unknown[]=[]
	let cancel=false
	for(const target of [dialog,menu])target.addEventListener('command',event=>{events.push({target:target.id,command:Reflect.get(event,'command'),cancelable:event.cancelable});if(cancel)event.preventDefault()})
	button.setAttribute('commandfor',dialog.id);button.setAttribute('command','show-modal')
	await userEvent.click(button);const opened=dialog.open;dialog.close();await settleFrame()
	cancel=true;await userEvent.click(button);const prevented=dialog.open
	cancel=false;button.setAttribute('command','--custom');await userEvent.click(button);const custom=dialog.open
	button.setAttribute('commandfor',menu.id);button.setAttribute('command','toggle-popover');await userEvent.click(button);const popover=menu.matches(':popover-open');menu.hidePopover();await settleFrame()
	cancel=true;await userEvent.click(button);const popoverPrevented=menu.matches(':popover-open')
	expect(opened).toBe(true);expect(prevented).toBe(false);expect(custom).toBe(false);expect(popover).toBe(true);expect(popoverPrevented).toBe(false)
	await writeReading('invoker-commands',11,{commands:['show-modal','toggle-popover','--custom']},{opened,prevented,popover,popoverPrevented,events},{expected:'--custom dispatches a command event but does not open the dialog.',reading:{custom,events:events.filter(event=>typeof event==='object'&&event!==null&&Reflect.get(event,'command')==='--custom')}},'Built-in invoker commands perform their action and cancelable command events can prevent it.')
	dialog.remove();menu.remove();button.remove()
})

