import { it, expect } from 'vitest'
import { cdp, userEvent } from 'vitest/browser'
import FocusTrap from 'bootstrap/js/src/util/focustrap.js'
import ScrollBarHelper from 'bootstrap/js/src/util/scrollbar.js'
import { makeElement, readBox, readTabs, settleFrame, writeReading } from './helpers.js'

it('measures inert against Bootstrap focus trap',async()=>{
	const before=makeElement('button');before.id='outside-before';before.textContent='Outside before'
	const modal=makeElement('div','modal show','display:block');modal.tabIndex=-1
	const first=makeElement('button','','',modal);first.id='inside-first';first.textContent='Inside first'
	const last=makeElement('button','','',modal);last.id='inside-last';last.textContent='Inside last'
	const after=makeElement('button','','position:fixed;bottom:0;z-index:2000');after.id='outside-after';after.textContent='Outside after'
	await userEvent.click(last);const control=await readTabs(last,5)
	const axBefore=await readAccessibility()
	const children=Array.from(document.body.children).filter(element=>element!==modal&&element instanceof HTMLElement)
	for(const element of children)if(element instanceof HTMLElement)element.inert=true
	await userEvent.click(last);const inert=await readTabs(last,5)
	const focusContext={hasFocus:document.hasFocus(),parentActive:window.parent.document.activeElement?.outerHTML.slice(0,400)}
	const visibility={before:before.getClientRects().length,after:after.getClientRects().length,aria:[before.getAttribute('aria-hidden'),after.getAttribute('aria-hidden')]}
	const accessibility=await readAccessibility()
	for(const element of children)if(element instanceof HTMLElement)element.inert=false
	const trap=new FocusTrap({trapElement:modal});trap.activate();await userEvent.click(last);const trapped=await readTabs(last,5);trap.deactivate()
	expect(control).toContain('outside-after');expect(inert).not.toContain('outside-after');expect(trapped).not.toContain('outside-after');expect(visibility.after).toBeGreaterThan(0)
	await writeReading('focus-inert',7,{start:'inside-last',tabs:5},{inert,trapped,visibility,accessibility,focusContext},{expected:'Without inert and without FocusTrap, Tab reaches outside-after and the accessibility tree includes outside controls; inert excludes both.',reading:{tabs:control,accessibility:axBefore}},'Inert excludes outside controls without removing their layout boxes or writing aria-hidden; frame-boundary focus is reported as observed.')
	before.remove();modal.remove();after.remove()
})

it('measures scroll lock and scrollbar gutter',async()=>{
	await cdp().send('Emulation.setScrollbarsHidden', { hidden: false })
	const tall=makeElement('div','','height:2600px')
	const navbar=makeElement('div','fixed-top','height:40px');navbar.textContent='Navigation'
	await settleFrame()
	const before={client:document.documentElement.clientWidth,inner:innerWidth,body:readBox(document.body),navbar:readBox(navbar),padding:getComputedStyle(document.body).paddingRight,navPadding:getComputedStyle(navbar).paddingRight}
	document.body.style.overflow='hidden';await settleFrame()
	const neither={client:document.documentElement.clientWidth,body:readBox(document.body),navbar:readBox(navbar)}
	document.body.style.overflow='';await settleFrame()
	const helper=new ScrollBarHelper();helper.hide();await settleFrame()
	const bootstrap={client:document.documentElement.clientWidth,body:readBox(document.body),navbar:readBox(navbar),padding:getComputedStyle(document.body).paddingRight,navPadding:getComputedStyle(navbar).paddingRight,inline:document.body.style.cssText,navbarInline:navbar.style.cssText};helper.reset()
	document.documentElement.style.scrollbarGutter='stable';await settleFrame()
	const stableBefore={client:document.documentElement.clientWidth,body:readBox(document.body),navbar:readBox(navbar)}
	document.body.style.overflow='hidden';await settleFrame()
	const stableAfter={client:document.documentElement.clientWidth,body:readBox(document.body),navbar:readBox(navbar),padding:getComputedStyle(document.body).paddingRight,navPadding:getComputedStyle(navbar).paddingRight}
	let launch:unknown;try{launch=await cdp().send('Browser.getBrowserCommandLine')}catch(error){launch=JSON.stringify(error)}
	const scrollbar=before.inner-before.client
	expect(scrollbar).toBeGreaterThan(0);expect(neither.body.width-before.body.width).toBe(scrollbar);expect(stableAfter.body.width).toBe(stableBefore.body.width);expect(stableAfter.navbar.width).toBe(stableBefore.navbar.width)
	await writeReading('scroll-lock',8,{viewport:{width:innerWidth,height:innerHeight},launch},{before,scrollbar,bootstrap,stableBefore,stableAfter},{expected:'With a classic scrollbar, hiding overflow without compensation widens body by the scrollbar width; stable gutter preserves width. A zero scrollbar width leaves the comparison untested.',reading:neither},scrollbar>0?'Classic scrollbar widths expose whether gutter preserves body and navbar geometry.':'Overlay scrollbars make width compensation moot in this run.')
	document.body.style.overflow='';document.documentElement.style.scrollbarGutter='';tall.remove();navbar.remove()
})

async function readAccessibility(){
	try{
		const tree=await cdp().send('Page.getFrameTree')
		const frames=[tree.frameTree]
		const results=[]
		for(const frame of frames){
			frames.push(...frame.childFrames??[])
			const ax=await cdp().send('Accessibility.getFullAXTree',{frameId:frame.frame.id})
			if(frame.frame.url.includes('iframeId='))results.push({url:frame.frame.url,nodes:ax.nodes.filter(node=>node.role?.value==='button').map(node=>({name:node.name?.value,ignored:node.ignored}))})
		}
		return results
	}catch(error){return {error:JSON.stringify(error)}}
}

