import { it, expect } from 'vitest'
import { cdp, userEvent } from 'vitest/browser'
import { waitForDelay } from '@orkestrel/test'
import { createOracle } from '../../../tests/setupBrowser.js'
import { createDropdown, createTooltip, Lock } from '../../../src/browser/index.js'
import { readBox, settleFrame, writeReading } from './helpers.js'

it('compares native modal constraints with Bootstrap in its oracle frame', async () => {
 const oracle = await createOracle({ plugin: 'Modal', frame: { width: 414, height: 896 }, markup: '<button id="outside">Outside</button><dialog class="modal" id="modal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><button id="first">First</button><button id="last">Last</button></div></div></dialog>' })
 try {
  const modal = oracle.document.querySelector('dialog')
  const outside = oracle.document.querySelector('button')
  if (!modal || !outside) throw Error('fixture')
  const instance = oracle.construct(modal, 'Modal', { focus: false })
  instance.call('show'); await settleFrame(); outside.focus()
  const bootstrap = { open: modal.open, modal: modal.matches(':modal'), focus: oracle.document.activeElement?.id, box: readBox(modal), border: getComputedStyle(modal).borderWidth, backdrop: oracle.document.querySelectorAll('.modal-backdrop').length }
  instance.call('hide'); instance.call('dispose')
  modal.removeAttribute('aria-hidden'); modal.style.display = 'block'; modal.classList.add('show')
  const style = oracle.document.createElement('style')
  style.textContent = 'dialog.modal{margin:0;border:0;padding:0;max-width:none;max-height:none;color:inherit;background:transparent}dialog.modal::backdrop{background:transparent}'
  oracle.document.head.append(style)
  modal.setAttribute('closedby', 'none'); outside.focus(); modal.showModal(); outside.focus()
  const events: string[] = []
  modal.addEventListener('cancel', () => events.push('cancel'))
  modal.addEventListener('keydown', event => { if (event.key === 'Escape') events.push('keydown') })
  await userEvent.keyboard('{Escape}'); await settleFrame()
  const native = { open: modal.open, modal: modal.matches(':modal'), focus: oracle.document.activeElement?.id, events: [...events], box: readBox(modal), backdrop: getComputedStyle(modal, '::backdrop').backgroundColor }
  expect(bootstrap.modal).toBe(false); expect(bootstrap.focus).toBe('outside'); expect(native.modal).toBe(true); expect(native.focus).not.toBe('outside'); expect(native.events).toContain('keydown'); expect(native.events).not.toContain('cancel')
  modal.close(); outside.focus(); expect(oracle.document.activeElement).toBe(outside)
  await writeReading('oracle-dialog-stage-b', 3, { focus: false, closedby: 'none' }, { bootstrap, native }, { outsideAfterClose: oracle.document.activeElement?.id }, 'Native modal exclusion and opening focus differ even with Bootstrap focus:false; closedby none leaves Escape on the keydown path.')
 } finally { oracle.destroy() }
})

it('compares stable gutter with Bootstrap modal compensation in its oracle frame', async () => {
 const oracle = await createOracle({ plugin: 'Modal', frame: { width: 414, height: 896 }, markup: '<div style="height:2600px"></div><nav class="fixed-top">Nav</nav><div class="modal" tabindex="-1"><div class="modal-dialog"><div class="modal-content">Modal</div></div></div>' })
 try {
  const modal = oracle.document.querySelector<HTMLElement>('.modal')
  const nav = oracle.document.querySelector('nav')
  if (!modal || !nav) throw Error('fixture')
  oracle.document.documentElement.style.scrollbarGutter = 'stable'
  await settleFrame()
  const before = { body: readBox(oracle.root), nav: readBox(nav), scrollbar: oracle.window.innerWidth - oracle.document.documentElement.clientWidth }
  const instance = oracle.construct(modal, 'Modal', { focus: false })
  instance.call('show'); await settleFrame()
  const bootstrap = { body: readBox(oracle.root), padding: getComputedStyle(oracle.root).paddingRight, nav: readBox(nav), navPadding: getComputedStyle(nav).paddingRight, modalPadding: modal.style.paddingRight }
  instance.call('hide'); instance.call('dispose')
  const lock = new Lock(oracle.document); lock.acquire(); await settleFrame()
  const tip = { body: readBox(oracle.root), padding: getComputedStyle(oracle.root).paddingRight }; lock.destroy()
  oracle.root.style.overflow = 'hidden'; await settleFrame()
  const native = { body: readBox(oracle.root), nav: readBox(nav), padding: getComputedStyle(oracle.root).paddingRight, navPadding: getComputedStyle(nav).paddingRight }
  expect(before.scrollbar).toBe(15); expect(bootstrap.padding).toBe('15px'); expect(tip.padding).toBe('15px'); expect(native.padding).toBe('0px'); expect(native.body.width).toBe(before.body.width)
  await writeReading('oracle-gutter-stage-b', 3, { gutter: 'stable' }, { before, bootstrap, tip, native }, { expected: 'Existing Bootstrap and Veneer still add 15px padding with a stable gutter.' }, 'A gutter opt-in must bypass body, fixed, sticky and modal compensation together.')
