it('records the real Bootstrap modal oracle',async()=>{
	const modal=makeElement('div','modal fade');modal.id='oracle-modal';modal.tabIndex=-1;modal.setAttribute('aria-hidden','true')
	modal.innerHTML='<div class="modal-dialog"><div class="modal-content"><button>Inside oracle</button></div></div>'
	const start=performance.now();const sequence:unknown[]=[];const transitions:unknown[]=[];const absent:unknown[]=[]
	const observer=new MutationObserver(records=>recordMutations(records,sequence,start))
	observer.observe(document.body,{attributes:true,attributeOldValue:true,childList:true,subtree:true})
	for(const name of ['show.bs.modal','shown.bs.modal','hide.bs.modal','hidden.bs.modal'])modal.addEventListener(name,event=>{recordMutations(observer.takeRecords(),sequence,start);sequence.push({event:name,time:performance.now()-start,cancelable:event.cancelable})})
	modal.addEventListener('opened.bs.modal',event=>absent.push(event.type))
	document.body.addEventListener('transitionend',event=>{transitions.push({target:describeNode(event.target),property:event instanceof TransitionEvent?event.propertyName:undefined,elapsed:event instanceof TransitionEvent?event.elapsedTime:undefined,time:performance.now()-start,isTrusted:event.isTrusted})},true)
	const instance=new Modal(modal)
	const shown=waitForEvent(listener=>{modal.addEventListener('shown.bs.modal',listener);return()=>modal.removeEventListener('shown.bs.modal',listener)},'Bootstrap modal shown',{budget:1500})
	instance.show();await shown
	const hidden=waitForEvent(listener=>{modal.addEventListener('hidden.bs.modal',listener);return()=>modal.removeEventListener('hidden.bs.modal',listener)},'Bootstrap modal hidden',{budget:1500})
	instance.hide();await hidden;await settleFrame();recordMutations(observer.takeRecords(),sequence,start);observer.disconnect();instance.dispose()
	const wrapper=makeElement('div','dropdown');const button=makeElement('button','dropdown-toggle','',wrapper);button.textContent='Oracle dropdown';button.setAttribute('data-bs-toggle','dropdown');const menu=makeElement('ul','dropdown-menu','',wrapper);menu.innerHTML='<li><button class="dropdown-item">Action</button></li>'
	const dropdown=new Dropdown(button);dropdown.show();await settleFrame();const dropdownShown={shown:menu.classList.contains('show'),placement:menu.getAttribute('data-popper-placement'),inline:menu.style.cssText};dropdown.hide();const dropdownHidden=!menu.classList.contains('show');dropdown.dispose();wrapper.remove();modal.remove()
	expect(absent.length).toBe(0);expect(sequence.some(entry=>typeof entry==='object'&&entry!==null&&Reflect.get(entry,'event')==='shown.bs.modal')).toBe(true);expect(dropdownShown.shown).toBe(true)
	await writeReading('bootstrap-oracle',9,{imports:['bootstrap/js/src/modal.js','bootstrap/js/src/dropdown.js'],observe:{attributes:true,attributeOldValue:true,childList:true,subtree:true},reconstruction:'Attribute new values use the next mutation oldValue for the same target/name, or the live value at delivery; pending mutations are drained before lifecycle events.'},{sequence,transitions,dropdownShown,dropdownHidden},{expected:'opened.bs.modal never fires while show/shown/hide/hidden do.',reading:absent},'Bootstrap Modal and Dropdown ESM sources resolve and run; the chronological observer transcript preserves old and reconstructed new attribute values.')
})

function describeNode(node: EventTarget|null):string {
	return node instanceof Element ? node.tagName.toLowerCase()+(node.id?'#'+node.id:'')+(node.className?'.'+String(node.className).replaceAll(' ','.'):'') : String(node)
}
function recordMutations(records:readonly MutationRecord[],sequence:unknown[],start:number) {
	for(const [index,record]of records.entries()){
		const next=records.slice(index+1).find(candidate=>candidate.target===record.target&&candidate.attributeName===record.attributeName&&candidate.type==='attributes')
		sequence.push({mutation:record.type,target:describeNode(record.target),attribute:record.attributeName,old:record.oldValue,value:record.type==='attributes'?(next?next.oldValue:record.target instanceof Element&&record.attributeName?record.target.getAttribute(record.attributeName):null):undefined,added:Array.from(record.addedNodes).map(describeNode),removed:Array.from(record.removedNodes).map(describeNode),time:performance.now()-start})
	}
}

